def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    desperate_count = 0
    error_count = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)
            if prev.get('error'):
                error_count += 1

    alive_n = len(alive)
    total_players = alive_n + 1
    units = int(supply // WATER_REQ)
    scarcity = units < total_players
    severe_scarcity = units <= max(0, total_players - 2)

    if budget <= 0:
        return 0

    if hp <= 2 or no_water >= 2:
        emergency = DAILY_SALARY * 0.95
        if prev_bids:
            emergency = max(emergency, max(prev_bids) + 1.0)
        return min(budget, emergency)

    if hp <= 4 or no_water >= 1:
        pressure_bid = DAILY_SALARY * 0.72
        if prev_bids:
            pressure_bid = max(pressure_bid, min(DAILY_SALARY * 0.9, max(prev_bids) + 1.0))
        if not scarcity:
            pressure_bid *= 0.9
        return min(budget, pressure_bid)

    if prev_bids:
        top_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        top_prev = 0
        avg_prev = 0

    if not scarcity:
        bid = DAILY_SALARY * 0.34
        if top_prev > 0:
            bid = min(DAILY_SALARY * 0.55, max(bid, avg_prev * 0.85))
        if error_count > 0:
            bid *= 0.92
    elif severe_scarcity:
        bid = DAILY_SALARY * 0.68
        if top_prev > 0:
            bid = max(bid, min(DAILY_SALARY * 0.88, top_prev + 1.0))
        if desperate_count >= max(1, alive_n // 2):
            bid += 4.0
    else:
        bid = DAILY_SALARY * 0.52
        if top_prev > 0:
            bid = max(bid, min(DAILY_SALARY * 0.78, top_prev + 0.5))
        if desperate_count > 0:
            bid += 2.0

    if budget < DAILY_SALARY * 1.5:
        bid *= 0.9
    if budget < DAILY_SALARY:
        bid *= 0.82

    if bid < 0:
        bid = 0
    return min(budget, bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = [o for o in opponents_status.values() if o.get('alive')]

    # Default: moderate bid.
    # Target is to roughly cover our requirement when supply is near the low end.
    # We also scale with how constrained we are (hp/no_water_days).
    if supply <= (MIN_SUPPLY + MAX_SUPPLY) / 2.0:
        base = 0.55 * DAILY_SALARY
    else:
        base = 0.45 * DAILY_SALARY

    # Escalate if we're in danger.
    risk = 0.0
    if hp <= 2.5:
        risk += 0.45
    elif hp <= 4.0:
        risk += 0.25

    if no_water_days >= 2:
        risk += 0.25
    elif no_water_days >= 1:
        risk += 0.12

    # Try to react to immediate yesterday pressure if available.
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If they were aggressive yesterday, we slightly outbid but only when it matters.
        if highest_prev_bid >= 0.85 * DAILY_SALARY:
            if hp > 3.5:
                base = 0.65 * DAILY_SALARY
            else:
                base = 0.95 * DAILY_SALARY
        else:
            # Otherwise, bid enough to be competitive.
            base = max(base, highest_prev_bid + 2.0)

    bid = base * (1.0 + risk)

    # Budget and sanity caps.
    # In this environment, bids are effectively bounded; keep within reasonable range.
    bid = min(bid, budget)
    bid = max(0.0, bid)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Determine base bid: conservative start
    base_bid = min(my_status['budget'], DAILY_SALARY * 0.4)

    # Look at previous traces if any
    if alive_opponents:
        prev_bids = []
        for opp in alive_opponents:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev['bid'])
        if prev_bids:
            max_prev = max(prev_bids)
            # If opponents bid aggressively yesterday, conservative today
            if max_prev >= DAILY_SALARY * 0.85:
                if my_status['hp'] > 3:
                    base_bid = min(my_status['budget'], DAILY_SALARY * 0.3)
                else:
                    base_bid = min(my_status['budget'], DAILY_SALARY * 0.9)
            else:
                base_bid = min(my_status['budget'], max(DAILY_SALARY * 0.5, max_prev + 1.5))

    # Adjust if low hp
    if my_status['hp'] <= 2:
        base_bid = max(base_bid, min(my_status['budget'], DAILY_SALARY * 0.85))

    # Ensure bid is integer (convert to int if needed)
    bid = int(base_bid)
    return min(bid, int(my_status['budget']))
